'use strict';
async function expLoadLists(){const token=novaCaptureSession(),result=await requestShared('/api/school/lists');if(novaSessionCurrent(token))exp.lists=result.lists}
async function expLoadHistory(input){const token=novaCaptureSession(),sequence=exp.historySequence=(exp.historySequence||0)+1;const from=input?.from||exp.history?.from||novaDate(),to=input?.to||exp.history?.to||from;const result=await requestShared('/api/school/history?'+new URLSearchParams({...input,from,to}));if(!novaSessionCurrent(token)||sequence!==exp.historySequence)return;exp.historyFilters={...input,from,to};exp.history=result;if(page==='school'&&naSchool.view==='history')schoolRender()}
const baseExperienceSchoolView=schoolView;schoolView=function(){if(!naSchool.data)return baseExperienceSchoolView();if(naSchool.trip)return schoolCallView();const canManage=naSchool.data.canManage,count=expQueue().length;return `${pageHead('Chamadas','Organize viagens e acompanhe cada presença.',canManage?schoolButton('new','Nova viagem','',true):'')}${count?`<div class="queue-banner" role="status"><strong>${count} marcação(ões) pendente(s) nesta aba.</strong><p>As presenças só estarão confirmadas após sincronizar com o servidor.</p>${expButton('queue-flush','Tentar sincronizar')}</div>`:''}<div class="tabs school-tabs">${[['today','Viagens do dia'],...(canManage?[['routes','Viagens'],['lists','Listas de alunos']]:[]),['history','Histórico']].map(([key,label])=>`<button data-school-action="view" data-view="${key}" class="${naSchool.view===key?'active':''}" ${naSchool.view===key?'aria-current="page"':''}>${label}</button>`).join('')}</div>${naSchool.view==='lists'?experienceListsView():naSchool.view==='routes'?schoolRoutesView():naSchool.view==='history'?schoolHistoryView():schoolTodayView()}`};
const baseExperienceRoutesView=schoolRoutesView;schoolRoutesView=function(){const html=baseExperienceRoutesView();return html.replace(/(<button type="button" data-school-action="edit"[^>]*data-route="([^"]+)"[^>]*>Editar viagem<\/button>)/g,(all,button,id)=>button+expButton('route-return','Criar volta',`data-route="${esc(id)}"`)+expButton('list-from-route','Guardar lista',`data-route="${esc(id)}"`))};
function experienceListsView(){return `<section class="panel"><div class="section-head"><div><h2>Listas reutilizáveis</h2><p class="help">Cadastre uma vez e escolha a lista ao criar a ida ou a volta. Viagens já cadastradas mantêm sua própria lista; chamadas iniciadas preservam o original.</p></div>${expButton('list-new','Nova lista','',true)}</div>${exp.lists.map(list=>`<div class="row"><div class="grow"><strong>${esc(list.name)}</strong><p>${esc(list.school)} · ${list.students.length} aluno(s)</p></div>${expButton('list-use','Criar viagem',`data-list="${esc(list.id)}"`)}${expButton('list-edit','Editar lista',`data-list="${esc(list.id)}"`)}</div>`).join('')||'<p class="help">Nenhuma lista guardada. Você também pode guardar a lista de uma viagem existente.</p>'}</section>`}
function expStudentInput(text,existing=[]){const available=[...existing];return text.split('\n').map(s=>s.trim()).filter(Boolean).map(name=>{const index=available.findIndex(s=>s.name===name),old=index<0?null:available.splice(index,1)[0];return {name,...(old?{id:old.id}:{})}})}
function experienceListForm(id,fromRoute){const old=id?exp.lists.find(l=>l.id===id):null,source=old||fromRoute||{},students=source.students||[],requestKey=expUserKey('nova-list-request-'+(id||'new')),requestId=expRead(requestKey)||uid();expWrite(requestKey,requestId);modal(old?'Editar lista de alunos':'Guardar lista de alunos','Use esta lista em novas viagens.',field('name','Nome da lista','text',old?.name||source.line||'','required maxlength="100"',true)+field('school','Escola / destino','text',source.school||'','required maxlength="120"',true)+opsArea('students','Alunos — um por linha',students.map(s=>s.name).join('\n'),true,12000)+'<p class="help full">Atualizar a lista não altera viagens existentes nem chamadas já iniciadas.</p>',async f=>{await requestShared('/api/school/lists'+(id?'/'+id:''),{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId,name:f.get('name'),school:f.get('school'),students:expStudentInput(f.get('students'),students),...(id?{version:old.version}:{})})});sessionStorage.removeItem(requestKey);closeModal();toast('Lista guardada para reutilizar.');try{await expLoadLists();schoolRender()}catch{toast('Lista salva. Atualize para consultar a versão atual.')}},'Salvar lista')}
schoolRouteForm=function(id,options={}){const d=naSchool.data,old=id?d.routes.find(r=>r.id===id):null,source=options.route||options.list||{},r=old||{line:source.line||options.list?.name||'',school:source.school||'',time:'',direction:options.returnTrip?'Volta':'Ida',students:source.students||[],weekdays:source.weekdays||[1,2,3,4,5],assignees:source.assignees||[]};const requestKey=expUserKey('nova-route-request-'+(id||'new')),requestId=expRead(requestKey)||uid();expWrite(requestKey,requestId);modal(id?'Editar viagem':options.returnTrip?'Criar viagem de volta':'Nova viagem','Cada horário e sentido têm uma chamada independente.',(!id&&exp.lists.length?`<label class="full">Reaproveitar lista de alunos<select id="exp-route-list"><option value="">Preencher ou manter os alunos abaixo</option>${exp.lists.map(l=>`<option value="${esc(l.id)}">${esc(l.name)} · ${esc(l.school)}</option>`).join('')}</select></label>`:'')+field('line','Linha','text',r.line,'required maxlength="80"')+field('school','Escola / destino','text',r.school,'required maxlength="120"')+field('time','Horário','time',r.time,'required')+opsSelect('direction','Sentido',[['Ida','Ida'],['Volta','Volta']],r.direction)+`<fieldset class="full school-checks"><legend>Dias da semana</legend>${[[1,'Seg'],[2,'Ter'],[3,'Qua'],[4,'Qui'],[5,'Sex'],[6,'Sáb'],[0,'Dom']].map(([n,l])=>`<label class="check"><input type="checkbox" name="weekdays" value="${n}" ${r.weekdays.includes(n)?'checked':''}>${l}</label>`).join('')}</fieldset><fieldset class="full school-assignees"><legend>Funcionários responsáveis</legend><p class="help">Somente os responsáveis vinculados terão acesso à viagem.</p>${d.employees.map(e=>`<label class="check"><input type="checkbox" name="assignees" value="${e.id}" ${r.assignees.includes(e.id)?'checked':''}>${esc(e.name)}${e.title?' · '+esc(e.title):''}</label>`).join('')}</fieldset>`+opsArea('students','Alunos — um por linha',r.students.map(s=>s.name).join('\n'),true,12000),async(f,form)=>{const input={requestId,line:f.get('line'),school:f.get('school'),time:f.get('time'),direction:f.get('direction'),weekdays:f.getAll('weekdays').map(Number),assignees:f.getAll('assignees'),students:expStudentInput(f.get('students'),form._studentSource||r.students),...(id?{version:r.version}:{})};await requestShared('/api/school/routes'+(id?'/'+id:''),{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});sessionStorage.removeItem(requestKey);closeModal();toast('Viagem salva na empresa.');try{await loadSchool()}catch{toast('Viagem salva. A atualização da lista está pendente.')}},'Salvar viagem');const form=document.getElementById('modal-form');document.getElementById('exp-route-list')?.addEventListener('change',e=>{const list=exp.lists.find(l=>l.id===e.target.value);if(!list)return;form.elements.students.value=list.students.map(s=>s.name).join('\n');form.elements.school.value=list.school;if(!form.elements.line.value)form.elements.line.value=list.name;form._studentSource=list.students;form.elements.students.dispatchEvent(new Event('input',{bubbles:true}))})};
schoolHistoryView=function(){const h=exp.history,from=h?.from||novaDate(),to=h?.to||novaDate();return `<section class="panel"><h2>Consultar chamadas</h2><form id="school-history-range" class="history-filters"><label>De<input type="date" name="from" value="${esc(from)}" max="${novaDate()}" required></label><label>Até<input type="date" name="to" value="${esc(to)}" max="${novaDate()}" required></label><label>Escola ou linha<input name="query" value="${esc(exp.historyFilters?.query||'')}" placeholder="Todas" maxlength="120"></label>${naSchool.data.canManage?opsSelect('assigneeId','Responsável',[['','Todos'],...(h?.employees||naSchool.data.employees).map(e=>[e.id,e.name])],exp.historyFilters?.assigneeId||'',false):''}<button type="submit" class="primary">Consultar período</button></form><p class="help">Até 93 dias por consulta. O acesso continua limitado às viagens permitidas à sua conta.</p></section>${h?`<div class="section-head"><p>${h.trips.length} chamada(s) encontrada(s)</p>${expButton('history-csv','Exportar CSV')}</div>${h.trips.map(t=>{const marked=Object.values(t.marks),yes=marked.filter(m=>m.value==='presente').length;return `<section class="panel"><div class="section-head"><div><span class="eyebrow">${fmt(t.date)} · ${esc(t.snapshot.time)} · ${esc(t.snapshot.direction)}</span><h2>${esc(t.snapshot.school)}</h2></div>${badge(t.status==='done'?'green':'yellow',t.status==='done'?'Concluída':'Em aberto')}</div><p>${esc(t.snapshot.line)} · ${yes} presente(s) · ${marked.length-yes} ausente(s) · ${t.snapshot.students.length-marked.length} sem marcação</p>${t.corrections.length?`<p class="help">${t.corrections.length} retificação(ões), com original preservado.</p>`:''}<div class="actions">${schoolButton('review','Ver chamada',`data-trip="${t.id}"`)}${expButton('trip-events','Ver alterações',`data-trip="${t.id}"`)}</div></section>`}).join('')||'<section class="panel"><p>Nenhuma chamada nesse período e nesses filtros.</p></section>'}`:'<p class="help" role="status">Carregando chamadas…</p>'}`};
function expQueue(){return novaCurrentUser()?expRead(expUserKey('nova-school-queue'),[]):[]}
function expSaveQueue(queue){if(!expWrite(expUserKey('nova-school-queue'),queue))throw Error('Não foi possível guardar a pendência neste aparelho. Mantenha a chamada aberta e tente com conexão.');}
function expAddPending(value){const queue=expQueue();if(queue.length>=300)throw Error('Há muitas marcações pendentes. Sincronize antes de continuar.');if(queue.some(q=>q.tripId===value.tripId&&q.studentId===value.studentId))throw Error('Esta marcação já está pendente. Sincronize ou confira o conflito antes de alterar.');queue.push(value);expSaveQueue(queue)}
function expCallRows(){const t=naSchool.trip,queue=expQueue().filter(q=>q.tripId===t.id),q=exp.search.toLocaleLowerCase('pt-BR'),readOnly=t.status==='done'||t.date!==naSchool.data.today;return t.snapshot.students.filter(s=>(!q||s.name.toLocaleLowerCase('pt-BR').includes(q))&&(!exp.onlyUnmarked||!t.marks[s.id])).map(s=>{const m=t.marks[s.id],pending=queue.find(p=>p.studentId===s.id),value=pending?.value||m?.value;return `<article class="school-student ${pending?'school-pending':''} ${exp.lastMark===s.id?'school-last':''}"><span class="avatar" aria-hidden="true">${esc(profileInitials(s.name))}</span><div class="school-student-name"><strong>${esc(s.name)}</strong><small>${pending?'Pendente de sincronização · '+(pending.value==='presente'?'Presente':'Ausente'):m?(m.value==='presente'?'Presente':'Ausente')+' · '+novaClock(m.at)+' · '+esc(m.actorName):'Ainda não marcado'}</small>${pending?.error?`<p class="error">${esc(pending.error)}</p>${expButton('queue-discard','Usar registro do servidor',`data-request="${esc(pending.requestId)}"`)}`:''}</div>${readOnly?badge(m?.value==='presente'?'green':m?'yellow':'pending',m?.value==='presente'?'Presente':m?'Ausente':'Sem marcação'):`<div class="school-choices">${['presente','ausente'].map(v=>`<button type="button" data-school-action="mark" data-student="${esc(s.id)}" data-value="${v}" class="school-choice ${value===v?'selected':''}" aria-pressed="${value===v}" ${naSchool.busy||pending?'disabled':''}>${v==='presente'?'Presente':'Ausente'}</button>`).join('')}</div>`}</article>`}).join('')||'<p class="help">Nenhum aluno neste filtro.</p>'}
schoolCallView=function(){const t=naSchool.trip,r=t.snapshot,marked=Object.keys(t.marks).length,pending=expQueue().filter(q=>q.tripId===t.id),readOnly=t.status==='done'||t.date!==naSchool.data.today;return `${schoolButton('back','Voltar às viagens')}<div class="page-head school-call-head"><div><p class="school-call-label">${esc(r.direction)} · ${esc(r.time)} · ${fmt(t.date)}</p><h1>${esc(r.school)}</h1><p>${esc(r.line)}</p></div>${badge(t.status==='done'?'green':'pending',t.status==='done'?'Concluída':readOnly?'Histórico':'Em andamento')}</div>${r.demo?'<p class="help">Demonstração com alunos fictícios.</p>':''}<div class="call-toolbar"><div class="call-progress" role="status"><strong>${marked} de ${r.students.length} confirmados</strong>${pending.length?`<span class="tag yellow">${pending.length} pendente(s)</span>`:''}${!readOnly?schoolButton('finish','Concluir chamada',`${naSchool.busy||pending.length||marked!==r.students.length?'disabled':''}`,true):''}</div><div class="call-filters"><label class="search">${icon('search')}<input id="call-search" value="${esc(exp.search)}" aria-label="Buscar aluno" placeholder="Buscar aluno"></label><label class="check"><input id="call-unmarked" type="checkbox" ${exp.onlyUnmarked?'checked':''}>Ainda não marcados</label></div>${exp.lastMark?`<p class="help call-last" role="status">Última confirmação: ${esc(r.students.find(s=>s.id===exp.lastMark)?.name||'aluno')}.</p>`:''}</div>${pending.length?`<div class="queue-banner" role="status"><strong>Há marcações ainda não confirmadas.</strong><p>Mantenha esta aba. Ao voltar a conexão, o app tenta sincronizar com a mesma identificação, sem duplicar. A conclusão só fica disponível depois da confirmação.</p>${expButton('queue-flush','Tentar sincronizar')}</div>`:''}<section class="panel school-students" id="call-students">${expCallRows()}</section>${t.corrections.length?`<details class="panel"><summary>${t.corrections.length} retificação(ões) administrativa(s)</summary>${t.corrections.map(c=>`<p><strong>${esc(c.actorName)}</strong> · ${fmt(c.at)} · ${novaClock(c.at)}<br>${esc(c.reason)}</p>`).join('')}<details><summary>Marcações originais</summary>${r.students.map(s=>`<p>${esc(s.name)}: ${t.originalMarks[s.id]?.value==='presente'?'Presente':t.originalMarks[s.id]?.value==='ausente'?'Ausente':'Sem marcação'}</p>`).join('')}</details></details>`:''}<div class="actions">${expButton('trip-events','Ver alterações',`data-trip="${t.id}"`)}${t.canCorrect?schoolButton('correct','Retificar chamada'):''}</div><p class="help">Horário e autoria são confirmados pelo servidor. Uma pendência no aparelho ainda não é uma presença salva.</p>`};
function expWireCall(){document.getElementById('call-search')?.addEventListener('input',e=>{exp.search=e.target.value;document.getElementById('call-students').innerHTML=expCallRows()});document.getElementById('call-unmarked')?.addEventListener('change',e=>{exp.onlyUnmarked=e.target.checked;document.getElementById('call-students').innerHTML=expCallRows()})}
async function expFlushQueue(){if(exp.queueBusy||novaAuth.stage!=='ready'||navigator.onLine===false)return;const token=novaCaptureSession();exp.queueBusy=true;try{for(const item of expQueue().filter(q=>!q.error)){if(!novaSessionCurrent(token))return;try{const result=await requestShared('/api/school/trips/'+item.tripId+'/sync-mark',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(item)});if(!novaSessionCurrent(token))return;expSaveQueue(expQueue().filter(q=>q.requestId!==item.requestId));if(naSchool.trip?.id===item.tripId){naSchool.trip=result.trip;exp.lastMark=item.studentId}}catch(e){if(e.staleSession)return;if(e.status>=400&&e.status<500){expSaveQueue(expQueue().map(q=>q.requestId===item.requestId?{...q,error:e.message}:q));continue}break}}}finally{if(novaSessionCurrent(token)){exp.queueBusy=false;if(page==='school'&&!document.getElementById('modal').open)schoolRender()}}}
const baseExperienceSchoolAction=schoolAction;schoolAction=async function(button){const action=button.dataset.schoolAction;if(action==='new'){await expLoadLists();return schoolRouteForm()}if(action==='view'&&button.dataset.view==='lists'){naSchool.view='lists';naSchool.trip=null;await expLoadLists();return schoolRender()}if(action==='view'&&button.dataset.view==='history'){naSchool.view='history';naSchool.trip=null;schoolRender();return expLoadHistory()}if(action==='mark'){if(naSchool.busy)return;const t=naSchool.trip,token=novaCaptureSession(),item={tripId:t.id,studentId:button.dataset.student,value:button.dataset.value,previous:t.marks[button.dataset.student]||null,requestId:uid()};if(navigator.onLine===false){expAddPending(item);schoolRender();return}naSchool.busy=true;schoolRender();try{const result=await requestShared('/api/school/trips/'+t.id+'/sync-mark',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(item)});if(!novaSessionCurrent(token))return;naSchool.trip=result.trip;exp.lastMark=item.studentId}catch(e){if(e.staleSession)return;if(!e.status||e.status>=500){expAddPending(item);toast('Marcação guardada nesta aba, pendente de confirmação.')}else{if(e.status===409)try{naSchool.trip=(await requestShared('/api/school/trips/'+t.id)).trip}catch{}throw e}}finally{if(novaSessionCurrent(token)){naSchool.busy=false;schoolRender()}}return}if(action==='finish'&&expQueue().some(q=>q.tripId===naSchool.trip?.id))throw Error('Sincronize as marcações pendentes antes de concluir.');const result=await baseExperienceSchoolAction(button);if(['open','review','back'].includes(action)){exp.search='';exp.onlyUnmarked=false;exp.lastMark='';if(page==='school')schoolRender()}return result};
async function experienceSchoolAction(button){const id=button.dataset.route;switch(button.dataset.expAction){case'route-return':await expLoadLists();return schoolRouteForm(null,{route:naSchool.data.routes.find(r=>r.id===id),returnTrip:true});case'list-from-route':return experienceListForm(null,naSchool.data.routes.find(r=>r.id===id));case'list-new':return experienceListForm();case'list-edit':return experienceListForm(button.dataset.list);case'list-use':return schoolRouteForm(null,{list:exp.lists.find(l=>l.id===button.dataset.list)});case'queue-flush':return expFlushQueue();case'queue-discard':{const item=expQueue().find(q=>q.requestId===button.dataset.request);if(!item)return;const result=await requestShared('/api/school/trips/'+item.tripId);expSaveQueue(expQueue().filter(q=>q.requestId!==item.requestId));if(naSchool.trip?.id===item.tripId)naSchool.trip=result.trip;return schoolRender()}case'history-csv':{const cell=x=>'"'+String(x??'').replace(/^[=+@\-]/,"'").replace(/"/g,'""')+'"',rows=[['Data','Horário','Escola','Linha','Sentido','Situação','Presentes','Ausentes','Sem marcação','Retificações'],...exp.history.trips.map(t=>{const marks=Object.values(t.marks),yes=marks.filter(m=>m.value==='presente').length;return [t.date,t.snapshot.time,t.snapshot.school,t.snapshot.line,t.snapshot.direction,t.status==='done'?'Concluída':'Em aberto',yes,marks.length-yes,t.snapshot.students.length-marks.length,t.corrections.length]})];return novaDownload('\uFEFF'+rows.map(row=>row.map(cell).join(';')).join('\r\n'),'chamadas-'+exp.history.from+'-'+exp.history.to+'.csv','text/csv;charset=utf-8')}case'trip-events':{const result=await requestShared('/api/school/trips/'+button.dataset.trip+'/events'),names=Object.fromEntries(result.trip.snapshot.students.map(s=>[s.id,s.name])),labels={'trip-started':'Viagem iniciada','attendance-marked':'Presença registrada','trip-finished':'Chamada concluída','trip-corrected':'Retificação administrativa'};return profileDialog('Alterações da chamada',result.trip.snapshot.school,result.events.map(event=>`<div class="event-entry"><strong>${esc(labels[event.event]||'Atualização')}</strong><p>${fmt(event.at)} · ${novaClock(event.at)} · ${esc(event.actorName)}</p>${event.details.studentId?`<p>${esc(names[event.details.studentId]||'Aluno')}: ${event.details.next?.value==='presente'?'Presente':'Ausente'}</p>`:''}${event.details.reason?`<p>${esc(event.details.reason)}</p>`:''}</div>`).join('')||'<p>Nenhuma alteração registrada.</p>',novaButton('close-nova','Fechar'))}}}

window.addEventListener('online',()=>expFlushQueue().catch(e=>toast(e.message)));
const originalExperienceLoadSchool=loadSchool;loadSchool=async function(){await originalExperienceLoadSchool();if(novaAuth.stage==='ready'&&expQueue().length)await expFlushQueue()};
bootNova();
